const seek = (rows: TableRow[], term: string) => {
  if (term === '') {
    return rows
  }

  return rows.filter((row) => {
    return Object.keys(row).some((key) => {
      const property = row[key]

      if (typeof property === 'string') {
        return property.match(new RegExp(term, 'i'))
      }

      return false
    })
  })
}

const slice = (
  rows: TableRow[],
  options: Record<string, number>,
  pagination: 'lengthAware' | 'simple' = 'lengthAware',
) => {
  const page =
    rows.length > (options.page - 1) * options.limit ? options.page : 1

  return rows.slice(
    page === 1 ? 0 : (page - 1) * options.limit,
    page * options.limit + (pagination === 'simple' ? 1 : 0),
  )
}

function Template({ pagination, ...args }: BasicTableProps): JSX.Element {
  const props = {
    ...args,
  }
  const [search, setSearch] = useState(() => '')
  const [options, setOptions] = useState(() => ({ page: 1, limit: 50 }))

  const handleChangePagination: HandlesPaginationChange = ({ page, limit }) => {
    setOptions({ page, limit })
  }

  const handleChangeSearch = (event: ChangeEvent<HTMLInputElement>) => {
    setSearch(event.target.value)
  }

  const filteredRows = seek(rows, search)
  const slicedRows = slice(filteredRows, options, pagination)

  return (
    <BasicTable
      key={pagination}
      pagination={pagination}
      total={filteredRows.length}
      {...props}
      columns={columns}
      rows={slicedRows}
    >
      <BasicTable.Header>
        <BasicTable.Title>Calendar Integration Users</BasicTable.Title>
        <BasicTable.GlobalActions>
          <Button startAdornment={ExpandMore} variant="outlined">
            CSV
          </Button>
          <Button color="primary" startAdornment={Refresh}>
            Refresh
          </Button>
        </BasicTable.GlobalActions>
        <BasicTable.BulkActions>
          <Button color="primary" startAdornment={CheckCircleOutline}>
            Enable Sync
          </Button>
          <Button color="primary" startAdornment={Block}>
            Disable Sync
          </Button>
          <Button color="primary" startAdornment={Refresh}>
            Refresh
          </Button>
        </BasicTable.BulkActions>
      </BasicTable.Header>
      <BasicTable.Toolbar>
        <BasicTable.Pagination onChange={handleChangePagination} />
        <BasicTable.Search onChange={handleChangeSearch} />
      </BasicTable.Toolbar>
    </BasicTable>
  )
}

export const Default = {
  render: Template,
}
