import clsx from 'clsx'
import React from 'react'
import type SvgIcon from '../SvgIcon/SvgIcon'
import type { AllColors } from '../utilities/colors'

export interface TagProps {
  /**
   * The color scheme of the tag
   * @default 'default'
   */
  color?: TagColor
  /**
   * The text content displayed in the tag
   */
  label: string
  /**
   * The size of the tag
   * @default 'medium'
   */
  size?: TagSize
  /**
   * Icon to display at the start of the tag
   */
  startAdornment?: typeof SvgIcon
}

type TagSize = 'large' | 'medium' | 'small'

type TagSizes = {
  [key in TagSize]: {
    root: string
    icon: string
    text: string
  }
}

type TagColor = AllColors

type TagColorStyles = {
  root: string
  text: string
  icon: string
}

type TagColors = {
  [key in TagColor]: TagColorStyles
}

const sizes: TagSizes = {
  large: {
    icon: 'w-5 mr-1',
    root: 'p-1',
    text: 'font-sans text-sm font-normal leading-4',
  },
  medium: {
    icon: 'w-4 mr-1',
    root: 'p-1',
    text: 'font-sans text-xs font-normal leading-3',
  },
  small: {
    icon: 'w-3 mr-0.5',
    root: 'p-0.75',
    text: 'font-sans text-xs font-normal leading-3',
  },
}

