function Tag({
  color = 'default',
  label,
  size = 'medium',
  startAdornment: StartAdornment,
}: TagProps): JSX.Element {
  return (
    <span
      className={clsx(
        'rounded-sm inline-flex cursor-default',
        colors[color].root,
        sizes[size].root,
      )}
    >
      <span className="flex items-center">
        {StartAdornment ? (
          <span className={clsx(sizes[size].icon, colors[color].icon)}>
            <StartAdornment />
          </span>
        ) : null}
        <span className={clsx('w-full', sizes[size].text, colors[color].text)}>
          {label}
        </span>
      </span>
    </span>
  )
}
export default Tag
